238	/**
239	 * Captures every durable fact Seam 2 death recovery must preserve.
240	 * @param store - Freshly reopened durable issuance authority.
241	 * @param scopes - Independently seeded exact scope inventory.
242	 * @returns Exact lineages, issued closures and outbox rows.
243	 */
244	export async function snapshotPhase3a1bP2Store(
245		store: Phase3a1bP2Store,
246		scopes: readonly Phase3a1bP2Scope[]
247	): Promise<Phase3a1bP2PublicationSnapshot> {
248		const rows = await store.readOutboxPage();
249		if (rows.length !== scopes.length) throw new TypeError("Seam 2 recovery has extra or missing outbox rows");
250		const issued = await Promise.all(scopes.map((scope) => store.readIssued(scope, 0)));
251		if (issued.some((commit) => commit === null)) throw new TypeError("Seam 2 recovery is missing one issued closure");
252		return {
253			issued: issued.map((commit) => snapshotRow(requiredCommit(commit))),
254			lineages: await Promise.all(
255				scopes.map(async (scope) => ({ ...(await store.readLineage(scope)), scope: { ...scope } }))
256			),
257			outbox: rows.map(({ commit, publishState }) => ({ ...snapshotRow(commit), publishState })),
258		};
259	}
