270	 * @returns Complete expected durable snapshot.
271	 */
272	export function expectedPhase3a1bP2Snapshot(
273		scenario: Phase3a1bP2Scenario | "already-published",
274		terminalFate: "exact-new" | "old"
275	): Phase3a1bP2PublicationSnapshot {
276		const commits = [deathCommit(PHASE_3A1B_P2_SCOPE, 41)];
277		if (scenario !== "single-row") commits.push(deathCommit(PHASE_3A1B_P2_OTHER_SCOPE, 73));
278		const published = scenario === "already-published" || terminalFate === "exact-new";
279		return {
280			issued: commits.map(snapshotRow),
281			lineages: commits.map((commit) => ({ exhausted: false, next: 1, scope: { ...commit.outboxEntry.scope } })),
282			outbox: commits.map((commit, index) => ({
283				...snapshotRow(commit),
284				publishState: index === 0 && published ? "published" : "pending",
285			})),
286		};
