329	/** Verifies both exact fourteen-tuple death registries. */
330	export function assertExactDeathRegistry(): void {
331		if (PHASE_3A1B_P2_DEATH_TUPLES.length !== 14)
332			throw new TypeError("Seam 2 death registry must contain fourteen tuples");
333		const ids = new Set(PHASE_3A1B_P2_DEATH_TUPLES.map(({ id }) => id));
334		if (ids.size !== 14) throw new TypeError("Seam 2 death tuple ids must be unique");
335		for (const tuple of PHASE_3A1B_P2_DEATH_TUPLES) {
336			const expected =
337				tuple.edge === "commit" ||
338				tuple.edge === "readback" ||
339				tuple.edge === "already-published-read" ||
340				tuple.edge === "already-published-commit"
341					? "exact-new"
342					: "old";
343			if (tuple.terminalFate !== expected) throw new TypeError(`wrong deterministic fate for ${tuple.id}`);
344		}
345		if (PHASE_3A1B_P2_BROWSER_DEATH_TUPLES.length !== 14) {
346			throw new TypeError("Seam 2 browser death registry must contain fourteen tuples");
347		}
348		if (new Set(PHASE_3A1B_P2_BROWSER_DEATH_TUPLES.map(({ id }) => id)).size !== 14) {
349			throw new TypeError("Seam 2 browser death tuple ids must be unique");
350		}
351	}

