82	function fallbackPlanValid(plan: TestSettlementPlan, scope: typeof F5B0S_SCOPE): boolean {
83		if (
84			plan.scope.author !== scope.author ||
85			plan.scope.objectId !== scope.objectId ||
86			!Number.isSafeInteger(plan.revision) ||
87			plan.revision < 0 ||
88			(plan.fenceSequence !== null && (!Number.isSafeInteger(plan.fenceSequence) || plan.fenceSequence < 0))
89		) {
90			return false;
91		}
92		let prior = -1;
93		for (const entry of plan.entries) {
94			if (
95				!Number.isSafeInteger(entry.sourceSequence) ||
96				entry.sourceSequence < 0 ||
97				entry.sourceSequence <= prior ||
98				!(entry.sourceDigest instanceof Uint8Array) ||
99				entry.sourceDigest.byteLength === 0 ||
100				!(["expire", "manual-review", "rebase", "transform"] as const).includes(entry.disposition) ||
101				(entry.replacementSequence !== null &&
102					(!Number.isSafeInteger(entry.replacementSequence) || entry.replacementSequence < 0))
103			) {
104				return false;
105			}
106			prior = entry.sourceSequence;
107		}
108		return true;
109	}
