111	function withFallbackPlanMethods(
112		raw: unknown,
113		cell: FallbackPlanCell
114	): Readonly<{ readonly nativePlanMethods: boolean; readonly store: TestPlanStore }> {
115		const candidate = raw as Record<string, unknown>;
116		const nativePlanMethods =
117			typeof Reflect.get(candidate, "readSettlementPlan") === "function" &&
118			typeof Reflect.get(candidate, "transactWriteSettlementPlan") === "function";
119		if (nativePlanMethods) return { nativePlanMethods, store: asPlanStore(raw) };
120		const base = raw as Omit<TestPlanStore, "readSettlementPlan" | "transactWriteSettlementPlan">;
121		return {
122			nativePlanMethods,
123			store: {
124				...base,
125				readSettlementPlan: () => Promise.resolve(cell.plan === null ? null : clonePlan(cell.plan)),
126				transactWriteSettlementPlan: (input) => {
127					if (!fallbackPlanValid(input.plan, input.scope as typeof F5B0S_SCOPE)) {
128						return Promise.reject(fallbackFailure("ISSUANCE_INVALID_ARGUMENT", "test fallback rejected plan"));
129					}
130					const observedRevision = cell.plan?.revision ?? null;
131					if (observedRevision !== input.expectedRevision) {
132						return Promise.reject(fallbackFailure("ISSUANCE_RETRY_REQUIRED", "test fallback CAS changed"));
133					}
134					if (input.plan.revision !== (input.expectedRevision === null ? 0 : input.expectedRevision + 1)) {
135						return Promise.reject(fallbackFailure("ISSUANCE_INVALID_ARGUMENT", "test fallback revision is not next"));
136					}
137					cell.plan = clonePlan(input.plan);
138					return Promise.resolve(clonePlan(cell.plan));
139				},
140			} as TestPlanStore,
141		};
142	}
