269	function createLegacyNodeV2(primaryFilename: string): void {
270		const database = new DatabaseSync(nodeDerived(primaryFilename));
271		const commit = settlementCommit(F5B0S_SCOPE, 0);
272		try {
273			database.exec("PRAGMA page_size=4096");
274			database.prepare("PRAGMA journal_mode=WAL").get();
275			database.exec("BEGIN IMMEDIATE");
276			database.exec(LEGACY_NODE_DDL.lineages);
277			database.exec(LEGACY_NODE_DDL.issuedRecords);
278			database.exec(LEGACY_NODE_DDL.issuanceOutbox);
279			database
280				.prepare(
281					"INSERT INTO lineages(object_id,author,next,exhausted,pruned_through_author_sequence) VALUES(?,?,?,?,NULL)"
282				)
283				.run(F5B0S_SCOPE.objectId, F5B0S_SCOPE.author, 1, 0);
284			database
285				.prepare(
286					"INSERT INTO issued_records(object_id,author,author_sequence,canonical_preimage,digest,signature) VALUES(?,?,?,?,?,?)"
287				)
288				.run(
289					F5B0S_SCOPE.objectId,
290					F5B0S_SCOPE.author,
291					0,
292					commit.envelope.canonicalPreimageBytes,
293					commit.envelope.digest,
294					commit.envelope.signature
295				);
296			database
297				.prepare("INSERT INTO issuance_outbox(object_id,author,author_sequence,digest,publish_state) VALUES(?,?,?,?,?)")
298				.run(F5B0S_SCOPE.objectId, F5B0S_SCOPE.author, 0, commit.envelope.digest, "published");
299			database.exec("PRAGMA user_version=2");
300			database.exec("COMMIT");
301		} finally {
302			database.close();
303		}
304	}
