108	/**
109	 *
110	 * @param sourceSequence
111	 * @param disposition
112	 * @param replacementSequence
113	 * @param seed
114	 */
115	export function settlementEntry(
116		sourceSequence: number,
117		disposition: SettlementDisposition = "rebase",
118		replacementSequence: number | null = null,
119		seed = sourceSequence + 17
120	): TestSettlementPlanEntry {
121		return {
122			disposition,
123			replacementSequence,
124			sourceDigest: Uint8Array.of(seed & 0xff, 0xd1),
125			sourceSequence,
126		};
127	}
128	
129	/**
130	 *
131	 * @param input
132	 */
133	export function settlementPlan(
134		input: Readonly<{
135			readonly entries?: readonly TestSettlementPlanEntry[];
136			readonly fenceSequence?: number | null;
137			readonly revision?: number;
138			readonly scope?: TestScope;
139		}> = {}
140	): TestSettlementPlan {
141		return {
142			entries: input.entries ?? [settlementEntry(10)],
143			fenceSequence: input.fenceSequence ?? null,
144			revision: input.revision ?? 0,
145			scope: input.scope ?? F5B0S_SCOPE,
146		};
147	}
