149	/**
150	 *
151	 * @param scope
152	 * @param authorSequence
153	 * @param effect
154	 * @param epoch
155	 */
156	export function settlementCommit(
157		scope: TestScope,
158		authorSequence: number,
159		effect?: TestPlanEffect,
160		epoch = 7
161	): TestCommit {
162		const envelope = {
163			canonicalPreimageBytes: encodeCanonical({
164				author: scope.author,
165				authorSequence,
166				epoch,
167				kind: "drp-vertex",
168				objectId: scope.objectId,
169				protocolMajor: 3,
170			}),
171			digest: Uint8Array.of(authorSequence + 31, 0xd1),
172			signature: Uint8Array.of(authorSequence + 31, 0x51),
173		};
174		return {
175			authorSequence,
176			envelope,
177			issuedRecord: { authorSequence, envelope, scope },
178			outboxEntry: { authorSequence, envelope, scope },
179			...(effect === undefined ? {} : { planEffect: effect }),
180		};
181	}
